import numpy as np
def equation(t, P, params):
    w1,w2,a,b,d,e,f,g,h,k = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    s1=np.sin(w1*t); c1=np.cos(w1*t); s2=np.sin(w2*t)
    return a + b*t + d*np.sqrt(P) + e*s1 + f*c1 + g*P*s2 + h*np.sin(2*w1*t) + k*np.cos(2*w1*t)
